    </div>
    <div class="metric-pill">
      <div class="label">Avg Retail Price</div>
      <div class="value">$191.17</div>
    </div>
    <div class="metric-pill">
      <div class="label">Avg Resale Price</div>
      <div class="value">$273.23</div>
    </div>
  </div>

  <div class="chart-row two">
    <div class="chart-box">
      <h3>Profit Margin Distribution</h3>
      <canvas id="profitDistChart"></canvas>
    </div>
    <div class="chart-box">
