      <canvas id="conditionRatioChart"></canvas>
    </div>
  </div>

  <table>
    <thead><tr><th>Condition</th><th>Transactions</th><th>Avg Retail</th><th>Avg Resale</th><th>Median Resale</th><th>Max Resale</th><th>Avg Profit</th><th>Margin %</th><th>Premium Rate</th><th>Avg Days</th></tr></thead>
    <tbody>
      <tr><td>Deadstock (Brand New)</td><td>1,678</td><td>$191.50</td><td>$455.51</td><td>$438.99</td><td>$804.58</td><td class="pos">+$264.01</td><td>137.7%</td><td><span class="tag tag-green">100%</span></td><td>23.0</td></tr>
      <tr><td>VNDS (Very Near Deadstock)</td><td>1,667</td><td>$192.21</td><td>$229.84</td><td>$232.33</td><td>$343.21</td><td class="pos">+$37.62</td><td>19.6%</td><td><span class="tag tag-orange">83%</span></td><td>21.7</td></tr>
      <tr><td>Used</td><td>1,655</td><td>$189.79</td><td>$132.13</td><td>$131.76</td><td>$204.63</td><td class="neg">−$57.66</td><td>−30.3%</td><td><span class="tag tag-red">0%</span></td><td>22.7</td></tr>
    </tbody>
  </table>

  <div class="chart-row two">
    <div class="chart-box">
      <h3>Profit by Condition × Model</h3>
      <canvas id="conditionModelChart"></canvas>
    </div>
    <div class="chart-box">
      <h3>Resale Price Range by Condition</h3>
      <canvas id="conditionRangeChart"></canvas>
    </div>
