from html.parser import HTMLParser
class Checker(HTMLParser):
    def __init__(self):
        super().__init__()
        self.errors = []
        self.tag_stack = []
        self.void_elements = {'meta','link','br','hr','img','input','canvas','source'}
    def handle_starttag(self, tag, attrs):
        if tag not in self.void_elements:
            self.tag_stack.append(tag)
    def handle_endtag(self, tag):
        if tag not in self.void_elements:
            if self.tag_stack and self.tag_stack[-1] == tag:
                self.tag_stack.pop()
            else:
                self.errors.append(f'Mismatched tag: </{tag}> (expected </{self.tag_stack[-1] if self.tag_stack else \"none\"}>)')
c = Checker()
with open('/app/output/final_report.html') as f:
    c.feed(f.read())
print(f'Unclosed tags: {c.tag_stack}')
print(f'Errors: {c.errors}')
print('OK' if not c.errors and not c.tag_stack else 'ISSUES FOUND')
"

